:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e8e8e8;
  --text-muted: #a0a0b0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --swatch-radius: 12px;
  --focus-ring: 3px solid #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at top, #16213e, #0f0f1a);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 32px 24px;
  max-width: 560px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  color: #fff;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 28px;
  line-height: 1.4;
}

.palette {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 28px;
}

.swatch-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: var(--swatch-radius);
  padding: 8px;
  transition: background 0.15s;
}

.swatch-color {
  width: 56px;
  height: 56px;
  border-radius: 10px;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: transform 0.2s;
}

.swatch-info {
  flex: 1;
  text-align: left;
  min-width: 0;
}

.swatch-hex {
  font-family: 'SF Mono', 'Cascadia Code', 'Fira Code', monospace;
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: #fff;
  text-transform: uppercase;
}

.swatch-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.lock-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.15);
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.15s;
  color: var(--text-muted);
  font-size: 1.1rem;
  line-height: 1;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(233, 69, 96, 0.1);
}

.lock-btn:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.92);
}

.lock-btn.locked {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(233, 69, 96, 0.15);
}

.lock-btn.locked:hover {
  background: rgba(233, 69, 96, 0.25);
}

.generate-btn {
  width: 100%;
  padding: 16px 24px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.98);
  background: #c73550;
}

@media (max-width: 420px) {
  .card {
    padding: 24px 16px;
  }

  h1 {
    font-size: 1.4rem;
  }

  .swatch-color {
    width: 44px;
    height: 44px;
  }

  .swatch-hex {
    font-size: 0.95rem;
  }

  .lock-btn {
    width: 40px;
    height: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

(function () {
  'use strict';

  const SWATCH_COUNT = 5;
  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  let colors = [];
  let locked = new Array(SWATCH_COUNT).fill(false);

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateHarmoniousPalette() {
    const baseHue = randomInt(0, 359);
    const scheme = Math.floor(Math.random() * 3);
    const hues = [];

    if (scheme === 0) {
      // Analogous
      const spread = randomInt(20, 40);
      for (let i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + (i - 2) * spread + 360) % 360);
      }
    } else if (scheme === 1) {
      // Complementary
      const complement = (baseHue + 180) % 360;
      hues.push(baseHue, complement, (baseHue + 30) % 360, (complement + 30) % 360, baseHue);
    } else {
      // Triadic
      const h2 = (baseHue + 120) % 360;
      const h3 = (baseHue + 240) % 360;
      hues.push(baseHue, h2, h3, (baseHue + 60) % 360, (h2 + 60) % 360);
    }

    const sat = randomInt(55, 80);
    return hues.map((h, i) => {
      const lightness = 35 + i * 8;
      return hslToHex(h, sat, Math.min(lightness, 75));
    });
  }

  function render() {
    paletteEl.innerHTML = '';
    colors.forEach((hex, i) => {
      const row = document.createElement('div');
      row.className = 'swatch-row';

      const colorBox = document.createElement('div');
      colorBox.className = 'swatch-color';
      colorBox.style.backgroundColor = hex;
      colorBox.setAttribute('role', 'img');
      colorBox.setAttribute('aria-label', `Color swatch ${i + 1}: ${hex}`);

      const info = document.createElement('div');
      info.className = 'swatch-info';

      const hexLabel = document.createElement('div');
      hexLabel.className = 'swatch-hex';
      hexLabel.textContent = hex;

      const label = document.createElement('div');
      label.className = 'swatch-label';
      label.textContent = `Swatch ${i + 1}`;

      info.appendChild(hexLabel);
      info.appendChild(label);

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn' + (locked[i] ? ' locked' : '');
      lockBtn.setAttribute('aria-pressed', String(locked[i]));
      lockBtn.setAttribute('aria-label', `${locked[i] ? 'Unlock' : 'Lock'} swatch ${i + 1}`);
      lockBtn.textContent = locked[i] ? '\u{1F512}' : '\u{1F513}';

      lockBtn.addEventListener('click', () => {
        locked[i] = !locked[i];
        render();
      });

      row.appendChild(colorBox);
      row.appendChild(info);
      row.appendChild(lockBtn);
      paletteEl.appendChild(row);
    });
  }

  function generate() {
    const fresh = generateHarmoniousPalette();
    colors = colors.length === SWATCH_COUNT
      ? colors.map((c, i) => (locked[i] ? c : fresh[i]))
      : fresh;
    render();
  }

  generateBtn.addEventListener('click', generate);

  // Initial palette
  colors = generateHarmoniousPalette();
  render();
})();
